    )
    const run = lane.steps.find((step) => step.env?.ORCA_E2E_SSH_DOCKER === '1').run
    expect(run).toContain('"${TEST_FILES[@]}"')
    expect(run).toContain('--shard="$SHARD"')
    for (const spec of [
      ORCAD_AUTO_CONVERT_E2E_SPEC,
