        if (!String(step.uses).startsWith('oven-sh/setup-bun@')) {
          continue
        }
        expect(step.with['bun-version-file'], file).toBe('config/.bun-version')
        expect(step.with['bun-version'], file).toBeUndefined()
      }
    }
  }
})

